script:
(() => {
    const root = root_element;
    const list = root.querySelector("#memento-todo-list");

    if (!list) {
        console.error("Could not find #memento-todo-list");
        return;
    }

    list.textContent = "Loading tasks...";

    frappe.call({
        method: "memento.api.get_workspace_todos",

        callback: function (response) {
            console.log("API response:", response);

            const result = response.message;

            if (!result || !result.success) {
                list.textContent = "Unable to load tasks.";
                return;
            }

            const items = result.items || [];

            list.replaceChildren();

            if (items.length === 0) {
                list.textContent = "No tasks found.";
                return;
            }

            items.forEach(function (row) {
                const item = document.createElement("div");
                item.className = "memento-todo-item";
                item.style.cursor = "pointer";

                // ToDo title and date
                const content = document.createElement("div");
                content.className = "memento-todo-item-content";

                const title = document.createElement("div");
                title.className = "memento-todo-item-title";
                title.textContent = row.task || "Untitled task";

                const date = document.createElement("div");
                date.className = "memento-todo-item-date";

                if (row.time) {
                    const parsedDate = new Date(
                        row.time.replace(" ", "T")
                    );

                    date.textContent = isNaN(parsedDate.getTime())
                        ? row.time
                        : parsedDate.toLocaleString();
                }

                content.appendChild(title);
                content.appendChild(date);

                // Right section
                const right = document.createElement("div");
                right.className = "memento-todo-item-right";

                // Status badge
                const status = document.createElement("span");
                status.className = "memento-todo-status";

                const statusValue = row.status || "Pending";
                status.textContent = statusValue;

                const normalizedStatus = statusValue.toLowerCase();

                if (
                    ["completed", "complete", "done"].includes(normalizedStatus)
                ) {
                    status.classList.add("memento-status-completed");
                } else if (
                    ["in progress", "working"].includes(normalizedStatus)
                ) {
                    status.classList.add("memento-status-progress");
                } else {
                    status.classList.add("memento-status-open");
                }

                // Arrow link
                const arrow = document.createElement("a");
                arrow.className = "memento-todo-arrow";
                arrow.textContent = "›";
                arrow.title = "Open ToDo";
                arrow.href = "/todo?" + new URLSearchParams({
                    todo: row.name || "",
                    task: row.parent || "",
                    project: row.project || ""
                }).toString();

                // Make the entire row clickable
                item.addEventListener("click", function (event) {
                    if (event.target.closest("a")) {
                        return;
                    }

                    window.location.href = arrow.href;
                });

                right.appendChild(status);
                right.appendChild(arrow);

                item.appendChild(content);
                item.appendChild(right);

                list.appendChild(item);
            });

            console.log("Displayed tasks:", items.length);
        },

        error: function (error) {
            console.error("API request failed:", error);
            list.textContent = "Failed to load tasks. Check console.";
        }
    });
})();

style:
.memento-todo-widget {
    width: 100%;
    height: 270px;
    padding: 18px 6px 0;
    box-sizing: border-box;
    font-family: inherit;
    background: #ffffff;

    /* Overflow effect */
    overflow-y: auto;
    overflow-x: hidden;
    scroll-behavior: smooth;
}

/* Custom scrollbar */
.memento-todo-widget::-webkit-scrollbar {
    width: 6px;
}

.memento-todo-widget::-webkit-scrollbar-track {
    background: #f5f0f5;
    border-radius: 10px;
}

.memento-todo-widget::-webkit-scrollbar-thumb {
    background: #c7b5cc;
    border-radius: 10px;
}

.memento-todo-widget::-webkit-scrollbar-thumb:hover {
    background: #8e7298;
}

.memento-todo-heading {
    font-size: 15px;
    font-weight: 500;
    color: #333333;
    margin-bottom: 18px;
}

#memento-todo-list {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.memento-todo-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 15px;
    width: 100%;
}

.memento-todo-item-content {
    flex: 1;
    min-width: 0;
}

.memento-todo-item-title {
    font-size: 14px;
    font-weight: 400;
    color: #444444;
    overflow-wrap: anywhere;
    margin-bottom: 4px;
}

.memento-todo-item-date {
    font-size: 11px;
    color: #888888;
}

.memento-todo-item-right {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;
}

.memento-todo-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 3px 10px;
    border-radius: 20px;
    font-size: 12px;
    white-space: nowrap;
}

.memento-todo-status::before {
    content: "";
    width: 6px;
    height: 6px;
    background: currentColor;
    border-radius: 50%;
}

.memento-status-open {
    color: #d12d32;
    background: #fff0f0;
}

.memento-status-completed {
    color: #168653;
    background: #eaf8f0;
}

.memento-status-progress {
    color: #a66b00;
    background: #fff5df;
}

.memento-todo-arrow {
    font-size: 19px;
    color: #777777;
    text-decoration: none;
    line-height: 1;
}

.memento-todo-arrow:hover {
    color: #333333;
}

.memento-todo-empty {
    padding: 18px 0;
    color: #888888;
    font-size: 13px;
}

.memento-todo-view-list {
    display: block;
    width: 100%;
    height: 27px;
    margin-top: 24px;
    padding: 3px 10px;
    border: none;
    border-radius: 9px;
    background: #f1f1f1;
    color: #555555;
    font-size: 14px;
    cursor: pointer;
    transition: background 0.2s ease;
}

.memento-todo-view-list:hover {
    background: #e5e5e5;
}
